// End-to-end VM/JavaScript smoke using public MIT KPassLib interoperability
// fixtures. Deliberately no Flutter, dart:io, browser DOM, or network imports.
import 'dart:convert';

import 'package:kpasslib/kpasslib.dart';
import 'package:xml/xml.dart';

KdbxCredentials _credentials() {
  final password = ProtectedData.fromString('demo');
  try {
    return KdbxCredentials(password: password, keyData: base64.decode(_key));
  } finally {
    password.dispose();
  }
}

void _check(bool value, String reason) {
  if (!value) throw StateError(reason);
}

XmlElement _entry(KdbxRawDocument raw) =>
    raw.xml.descendants.whereType<XmlElement>().firstWhere(
      (node) =>
          node.name.qualified == 'Entry' &&
          node.getElement('UUID')?.innerText == 'vqcoCvE9/k6PSgutKI6snw==',
    );

XmlElement _password(XmlElement entry) => entry
    .findElements('String')
    .firstWhere((field) => field.getElement('Key')?.innerText == 'Password')
    .getElement('Value')!;

Future<void> main() async {
  for (final item in _databases.entries) {
    final raw = await KdbxRawDocument.open(
      data: base64.decode(item.value),
      credentials: _credentials(),
      validateHeader: (_) {},
    );
    final entry = _entry(raw);
    _check(
      raw.textOf(_password(entry)) == 'mypass',
      'Fixture password decoding',
    );
    final history = entry.getElement('History')!;
    history.children.add(raw.cloneElement(entry, omitHistory: true));
    final custom = XmlElement(XmlName('FutureExtension'), [
      XmlAttribute(XmlName('Version'), 'keep-me'),
    ]);
    entry.children.insert(0, custom);
    raw.setText(custom, 'Unknown protected value', protected: true);
    raw.setText(_password(entry), 'Updated 🔑 password', protected: true);
    final saved = await raw.save();
    final savedAgain = await raw.save();
    _check(
      base64.encode(saved) != base64.encode(savedAgain),
      'Fresh encryption salts',
    );
    final reopened = await KdbxRawDocument.open(
      data: saved,
      credentials: _credentials(),
      validateHeader: (_) {},
    );
    final result = _entry(reopened);
    _check(
      reopened.textOf(_password(result)) == 'Updated 🔑 password',
      'Edited password round trip',
    );
    _check(
      reopened.textOf(result.getElement('FutureExtension')!) ==
          'Unknown protected value',
      'Unknown protected value round trip',
    );
    _check(
      result.getElement('FutureExtension')!.getAttribute('Version') ==
          'keep-me',
      'Unknown attribute retention',
    );
    _check(
      reopened.textOf(
            _password(result.getElement('History')!.findElements('Entry').last),
          ) ==
          'mypass',
      'History retention',
    );
    _check(
      reopened.header.version == raw.header.version,
      'Format version retention',
    );
    _check(
      reopened.header.dataCipherUuid == raw.header.dataCipherUuid,
      'Cipher retention',
    );
    reopened.dispose();
    raw.dispose();
    // Only fixed fixture labels and PASS metadata are printed, never values.
    // ignore: avoid_print
    print('PASS KeePass database ${item.key} open/edit/save/reopen');
  }
}

// Original upstream binary fixtures, unchanged apart from base64 transport.
// See test/fixtures/keepass/README.md and packages/kpasslib/LICENSE.
const _key =
    'PD94bWwgdmVyc2lvbj0iMS4wIiBlbmNvZGluZz0idXRmLTgiPz4NCjxLZXlGaWxlPg0KCTxNZXRhPg0KCQk8VmVyc2lvbj4xLjAwPC9WZXJzaW9uPg0KCTwvTWV0YT4NCgk8S2V5Pg0KCQk8RGF0YT5BdFkyR1IycFZ0NmFXejJ1Z2Z4ZlNRV2pSSWQ5bDBKV2UvTEVNSldWSjFrPTwvRGF0YT4NCgk8L0tleT4NCjwvS2V5RmlsZT4NCg==';
const _databases = <String, String>{
  'KDBX3 AES-KDF/AES': '',
  'KDBX4 Argon2id/AES': '',
  'KDBX4 Argon2d/ChaCha20': '',
};
